/**
 * utilgen — a small utility-class CSS generator in the Tailwind spirit.
 *
 * `generate(config)` produces a deterministic CSS string containing:
 *  - margin and padding utilities for all sides, x/y axes and individual
 *    edges (m-4, mx-2, my-1, mt-8, mr-4, mb-2, ml-1, and the p-* equivalents)
 *  - display utilities (block, inline-block, inline, flex, inline-flex,
 *    grid, hidden)
 *  - for every entry in the `screens` map, a prefixed variant of every
 *    utility wrapped in a media query (e.g. md:px-4 inside
 *    `@media (min-width: 768px)`), with colons escaped in selectors.
 */

export interface UtilGenConfig {
  /** Spacing scale, e.g. { '0': '0', '1': '0.25rem', ... } */
  spacing: Record<string, string>;
  /** Screen name -> min-width value, e.g. { md: '768px', lg: '1024px' } */
  screens?: Record<string, string>;
}

/** Display utilities: class suffix -> `display` value. Fixed order. */
export const DISPLAY_UTILITIES: ReadonlyArray<readonly [string, string]> = [
  ['block', 'block'],
  ['inline-block', 'inline-block'],
  ['inline', 'inline'],
  ['flex', 'flex'],
  ['inline-flex', 'inline-flex'],
  ['grid', 'grid'],
  ['hidden', 'none'],
] as const;

interface BoxSpec {
  prefix: string;
  props: string[];
}

/** Margin/padding prefixes in fixed order: box, axis, then individual edges. */
const BOX_SPECS: readonly BoxSpec[] = [
  { prefix: 'm', props: ['margin'] },
  { prefix: 'mx', props: ['margin-left', 'margin-right'] },
  { prefix: 'my', props: ['margin-top', 'margin-bottom'] },
  { prefix: 'mt', props: ['margin-top'] },
  { prefix: 'mr', props: ['margin-right'] },
  { prefix: 'mb', props: ['margin-bottom'] },
  { prefix: 'ml', props: ['margin-left'] },
  { prefix: 'p', props: ['padding'] },
  { prefix: 'px', props: ['padding-left', 'padding-right'] },
  { prefix: 'py', props: ['padding-top', 'padding-bottom'] },
  { prefix: 'pt', props: ['padding-top'] },
  { prefix: 'pr', props: ['padding-right'] },
  { prefix: 'pb', props: ['padding-bottom'] },
  { prefix: 'pl', props: ['padding-left'] },
];

/** Sort spacing keys numerically when possible, lexicographically otherwise. */
function sortedSpacingKeys(spacing: Record<string, string>): string[] {
  return Object.keys(spacing).sort((a, b) => {
    const na = Number(a);
    const nb = Number(b);
    if (!Number.isNaN(na) && !Number.isNaN(nb)) return na - nb;
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

/** Escape special characters (notably `:`) for use in a CSS selector. */
export function escapeSelector(name: string): string {
  return name.replace(/([:.#()[\]/%&*])/g, '\\$1');
}

function rule(selectorName: string, decls: string[]): string {
  const body = decls.map((d) => `  ${d};`).join('\n');
  return `.${escapeSelector(selectorName)} {\n${body}\n}`;
}

/**
 * All unprefixed rules for one screen layer.
 * Order: margin utilities then padding utilities, each in BOX_SPECS order,
 * scale keys ascending; then display utilities in DISPLAY_UTILITIES order.
 */
function buildLayer(prefix: string, spacingKeys: string[], spacing: Record<string, string>): string {
  const rules: string[] = [];
  for (const spec of BOX_SPECS) {
    for (const key of spacingKeys) {
      rules.push(
        rule(
          `${prefix}${spec.prefix}-${key}`,
          spec.props.map((prop) => `${prop}: ${spacing[key]}`),
        ),
      );
    }
  }
  for (const [name, value] of DISPLAY_UTILITIES) {
    rules.push(rule(`${prefix}${name}`, [`display: ${value}`]));
  }
  return rules.join('\n');
}

function indent(text: string): string {
  return text
    .split('\n')
    .map((line) => (line.length > 0 ? '  ' + line : line))
    .join('\n');
}

/** Generate the full stylesheet as a deterministic CSS string. */
export function generate(config: UtilGenConfig): string {
  const spacingKeys = sortedSpacingKeys(config.spacing);

  let css = buildLayer('', spacingKeys, config.spacing);

  // Screen variants follow base utilities, in screens-map insertion order.
  for (const [screen, minWidth] of Object.entries(config.screens ?? {})) {
    const body = buildLayer(`${screen}:`, spacingKeys, config.spacing);
    css += `\n@media (min-width: ${minWidth}) {\n${indent(body)}\n}`;
  }

  return css + '\n';
}

