import { describe, expect, it } from 'vitest';
import postcss from 'postcss';
import {
  DISPLAY_UTILITIES,
  generate,
  type UtilGenConfig,
} from '../src/index.js';

const config: UtilGenConfig = {
  spacing: { 0: '0', 1: '0.25rem', 2: '0.5rem', 4: '1rem', 8: '2rem' },
  screens: { md: '768px', lg: '1024px' },
};

const SPACING_KEYS = Object.keys(config.spacing).length; // 5
const BOX_PREFIXES = [
  'm', 'mx', 'my', 'mt', 'mr', 'mb', 'ml',
  'p', 'px', 'py', 'pt', 'pr', 'pb', 'pl',
]; // 14
const MARGIN_PREFIXES = BOX_PREFIXES.slice(0, 7);
const PADDING_PREFIXES = BOX_PREFIXES.slice(7);
const SCREENS = Object.entries(config.screens!); // [['md','768px'], ['lg','1024px']]

/** Rules contributed by one screen layer (base or any prefixed variant). */
const RULES_PER_LAYER =
  BOX_PREFIXES.length * SPACING_KEYS + DISPLAY_UTILITIES.length; // 70 + 7 = 77

function rulesOf(container: postcss.Container): postcss.Rule[] {
  return container.nodes!.filter((n): n is postcss.Rule => n.type === 'rule');
}

function mediasOf(root: postcss.Root): postcss.AtRule[] {
  return root.nodes!.filter(
    (n): n is postcss.AtRule => n.type === 'atrule' && n.name === 'media',
  );
}

describe('generate()', () => {
  it('matches the snapshot for the fixed config', () => {
    expect(generate(config)).toMatchSnapshot();
  });

  it('is deterministic across runs', () => {
    expect(generate(config)).toBe(generate(config));
    expect(generate(config)).toBe(generate({ ...config }));
  });

  it('produces exactly sides-times-scale rules in the base layer', () => {
    const root = postcss.parse(generate(config));
    const baseRules = rulesOf(root);

    // 14 box prefixes x 5 scale keys + display utilities.
    expect(baseRules).toHaveLength(RULES_PER_LAYER);

    const marginCount = baseRules.filter((r) =>
      r.selector.startsWith('.m'),
    ).length;
    const paddingCount = baseRules.filter((r) =>
      r.selector.startsWith('.p'),
    ).length;

    // 7 margin prefixes and 7 padding prefixes, each times the scale.
    expect(marginCount).toBe(MARGIN_PREFIXES.length * SPACING_KEYS); // 35
    expect(paddingCount).toBe(PADDING_PREFIXES.length * SPACING_KEYS); // 35

    // Every prefix appears exactly once per scale key in the base layer.
    for (const prefix of BOX_PREFIXES) {
      const count = baseRules.filter((r) =>
        r.selector.startsWith(`.${prefix}-`),
      ).length;
      expect(count).toBe(SPACING_KEYS);
    }
  });

  it('wraps one exact copy of every utility per screen variant', () => {
    const root = postcss.parse(generate(config));
    const medias = mediasOf(root);

    expect(medias).toHaveLength(SCREENS.length);

    medias.forEach((media, i) => {
      const [screen, minWidth] = SCREENS[i];
      expect(media.params).toBe(`(min-width: ${minWidth})`);
      const rules = rulesOf(media);
      expect(rules).toHaveLength(RULES_PER_LAYER);

      // Same math inside each media query: every prefix once per key.
      for (const prefix of BOX_PREFIXES) {
        const count = rules.filter((r) =>
          r.selector.startsWith(`.${screen}\\:${prefix}-`),
        ).length;
        expect(count).toBe(SPACING_KEYS);
      }
      // Display utilities are wrapped too.
      for (const [name] of DISPLAY_UTILITIES) {
        expect(rules.some((r) => r.selector === `.${screen}\\:${name}`)).toBe(
          true,
        );
      }
    });
  });

  it('puts md:px-4 with correct declarations inside @media (min-width: 768px)', () => {
    const root = postcss.parse(generate(config));
    const mdMedia = mediasOf(root).find((m) => m.params.includes('768px'));
    expect(mdMedia).toBeDefined();

    const target = rulesOf(mdMedia!).find((r) => r.selector === '.md\\:px-4');
    expect(target).toBeDefined();

    const decls = target!.nodes!.map((d) => `${(d as postcss.Declaration).prop}: ${(d as postcss.Declaration).value}`);
    expect(decls).toEqual([
      'padding-left: 1rem',
      'padding-right: 1rem',
    ]);
  });

  it('emits expected declaration values for a spot-checked rule set', () => {
    const css = generate(config);
    expect(css).toContain('.m-8 {\n  margin: 2rem;\n}');
    expect(css).toContain('.my-1 {\n  margin-top: 0.25rem;\n  margin-bottom: 0.25rem;\n}');
    expect(css).toContain('.hidden {\n  display: none;\n}');
  });
});

